# 헤드리스 이동·동작 검사: 탭, 설정 버튼, 가져오기 4단계, 화면 모드, 삭제 확인창, 입력 저장
from playwright.sync_api import sync_playwright
import os
d=os.path.dirname(os.path.abspath(__file__));errs=[];res=[]
def ok(n,c):res.append(('통과' if c else '실패')+' · '+n)
with sync_playwright() as p:
 b=p.chromium.launch();pg=b.new_page(viewport={'width':360,'height':780},accept_downloads=True);pg.on('pageerror',lambda e:errs.append(str(e)));pg.on('console',lambda m:m.type=='error' and errs.append(m.text))
 pg.goto(f'file://{d}/mockup.html');pg.wait_for_timeout(500)
 on=lambda:pg.evaluate("document.querySelector('.screen.on').id")
 for s in ['cal','chart','budget','home']:
  pg.click(f'.tab [data-s="{s}"]');ok(f'하단 탭 → {s}',on()==s)
 pg.click('#home .ib[aria-label="설정"]');ok('홈 설정 버튼 → 설정',on()=='settings')
 pg.click('#modeseg [data-m="dark"]');ok('설정 화면 모드 다크',pg.evaluate("A.classList.contains('dark')"))
 pg.click('#modeseg [data-m="light"]');ok('설정 화면 모드 라이트',not pg.evaluate("A.classList.contains('dark')"))
 pg.click('text=계정과 모든 기록 삭제');ok('삭제 확인창 열림',pg.is_visible('#dlg'));ok('삭제 버튼 처음엔 잠김',pg.is_disabled('#dlgdel'))
 pg.fill('#dlgi','삭제');ok("'삭제' 입력 후 버튼 풀림",pg.is_enabled('#dlgdel'));pg.click('.dlgb button >> nth=0');ok('취소로 닫힘',not pg.is_visible('#dlg'))
 pg.click('text=카드사·은행 파일 가져오기');ok('설정 → 가져오기',on()=='import');ok('가져오기에선 하단 탭 숨김',not pg.is_visible('.tab'))
 pg.click('text=예시 파일로 해 보기');ok('1→2단계',pg.evaluate('istep')==2)
 pg.click('#inext');ok('2→3단계',pg.evaluate('istep')==3)
 pg.click('#inext');ok('3→4단계, 버튼 문구',pg.evaluate('istep')==4 and '128건' in pg.inner_text('#inext'))
 pg.click('#inext');ok('4→완료',pg.evaluate('istep')==5 and not pg.is_visible('#ifoot'))
 pg.click('text=달력에서 보기');ok('완료 → 달력, 탭 다시 보임',on()=='cal' and pg.is_visible('.tab'))
 pg.click('.tab [data-s="chart"]');pg.click('#leg button >> nth=0');ok('도넛 범례 → 거래 목록(달력)',on()=='cal')
 pg.click('.tab [data-s="home"]');pg.click('.fab');pg.click('.key:text-is("1")');pg.click('.key:text-is("000")');pg.click('.cat >> nth=1');pg.click('#save');pg.wait_for_timeout(1200)
 ok('입력 저장 후 홈 숫자 갱신(20,000→19,000)','19,000' in pg.inner_text('#big').replace('\n',''))

 # ---- v3 추가 동작 ----
 pg.click('.tab [data-s="chart"]');pg.click('#cpill [data-v="inc"]');ok('차트 수입 전환',pg.inner_text('#ctitle')=='10월 어디서 들어왔을까' and '310만원' in pg.inner_text('#cval'))
 pg.click('#cpill [data-v="save"]');ok('차트 남긴 돈 전환',pg.inner_text('#cctr')=='남긴 돈')
 pg.click('#cpill [data-v="exp"]');pg.click('#leg button >> nth=0');ok('범례 식비 → 목록 보기 필터',on()=='cal' and pg.is_visible('#listv') and '식비만' in pg.inner_text('#listv'))
 pg.click('.fchip');ok('필터 지우기',not pg.query_selector('.fchip'))
 pg.click('#calt2 [data-v="cal"]');pg.click('#calnext');ok('다음 달 → 빈 상태',pg.inner_text('#calt')=='2026년 11월' and '예시 데이터에 없어요' in pg.inner_text('#daylist'))
 pg.click('#calprev');pg.click('.dy[data-d="19"]');ok('날짜 누르면 그날 기록',pg.inner_text('#seld').startswith('10월 19일') and '김치찌개' in pg.inner_text('#daylist'))
 pg.click('.tab [data-s="chart"]');pg.click('.bcol[data-i="2"]');ok('막대 누르면 수치 표시',pg.inner_text('#bsel').startswith('7월'))
 pg.click('.tab [data-s="home"]');pg.click('.fab');pg.click('#kseg [data-k="inc"]');ok('입력 시트 수입 전환',pg.inner_text('.cat >> nth=0').endswith('월급'))
 pg.click('#kseg [data-k="exp"]');pg.click('.cat >> nth=7');ok('더보기 → 다음 카테고리',pg.inner_text('.cat >> nth=0').endswith('주거·관리비'))
 pg.click('.cat >> nth=7');pg.click('#odate');pg.click('#opay');ok('날짜·결제수단 바꾸기',pg.inner_text('#odate').endswith('어제') and '현금' in pg.inner_text('#opay'))
 pg.click('#omemo');pg.fill('#memo','친구 선물');pg.click('.key:text-is("5")');pg.click('.key:text-is("000")');pg.click('.cat >> nth=0');pg.click('#save');pg.wait_for_timeout(1100)
 ok('메모 저장 반영',  '친구 선물' in pg.inner_text('#recent'))
 pg.click('#toast button');pg.wait_for_timeout(200);ok('되돌리기',  '친구 선물' not in pg.inner_text('#recent'))
 pg.click('.tab [data-s="budget"]');pg.click('#budget .ib');pg.fill('#bin','2000000');pg.click('#edlg .pri');ok('예산 수정 반영',pg.inner_text('#bbud')=='2,000,000원' and '62%' in pg.inner_text('#bring'))
 pg.click('#bsplit');ok('나눠서 관리 끄기',  '총예산 하나로만' in pg.inner_text('#envs'));pg.click('#bsplit');ok('다시 켜기',  '식비' in pg.inner_text('#envs'))
 pg.click('#budget .ib');pg.fill('#bin','1500000');pg.click('#edlg .pri')
 pg.click('.tab [data-s="home"]');pg.click('#home .ib[aria-label="설정"]')
 pg.click('#emgrid .emc >> nth=0');pg.fill('#cname','밥값');pg.click('#empick button >> nth=2');pg.click('#edlg .pri');ok('카테고리 이름·이모지 편집',  '밥값' in pg.inner_text('#emgrid') and '🍜' in pg.inner_text('#emgrid'))
 pg.click('#emgrid .emc.add');pg.fill('#cname','반려동물');pg.click('#empick button >> nth=16');pg.click('#edlg .pri');ok('카테고리 추가',  '반려동물' in pg.inner_text('#emgrid'))
 pg.click('#ekp [data-k="inc"]');ok('수입 카테고리 탭',  '월급' in pg.inner_text('#emgrid'))
 pg.click('text=결제수단');pg.fill('#pname','신한카드');pg.click('#edlg .pri');ok('결제수단 추가',  '신한카드' in pg.inner_text('#edlgc'));pg.click('#edlg .dlgb button >> nth=0');ok('결제수단 요약 갱신',  '신한카드' in pg.inner_text('#payv'))
 with pg.expect_download() as dl: pg.click('text=CSV로 내보내기')
 ok('CSV 내려받기',dl.value.suggested_filename.endswith('.csv'))
 with pg.expect_download() as dl2: pg.click('text=전체 백업(JSON)')
 ok('JSON 내려받기',dl2.value.suggested_filename.endswith('.json'))
 pg.click('text=카드사·은행 파일 가져오기');pg.set_input_files('#ifile',files=[{'name':'신한카드_10월.xls','mimeType':'application/vnd.ms-excel','buffer':b'x'}]);ok('파일 선택 → 2단계',pg.evaluate('istep')==2)
 pg.click('#cenc');ok('인코딩 칩 전환',  'EUC-KR' in pg.inner_text('#cenc'));pg.select_option('#mhead th >> nth=3 >> select','무시');ok('열 용도 바꾸기',True)
 pg.click('#inext');pg.click('.mini >> nth=0 >> button >> nth=1');pg.click('#skipall');ok('모두 건너뛰기',pg.evaluate("[...document.querySelectorAll('.mini')].every(m=>m.children[0].classList.contains('on'))"))
 pg.click('#inext');ok('확정 화면에 파일 이름',pg.inner_text('#fname')=='신한카드_10월.xls');pg.click('#inext');pg.click('#iundo');ok('완료 후 되돌리기 → 설정',on()=='settings')
 pg.keyboard.press('Escape')
 b.close()
print('\n'.join(res));print('JS 오류:',errs or '없음')
